const currency=(n:any)=>n==null?'Not recorded':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const labels:Record<string,string>={Received:'RCVD',Production:'PROD',InProgress:'IN PROGRESS',Incomplete:'INC',Closed:'COMP',Ordered:'ORD',UTI:'UTI',COLL:'COLL',SVC:'SVC'};
const paymentMethods=[{id:'FNC',name:'Finance (FNC)'},{id:'CHK',name:'Check (CHK)'},{id:'CC',name:'Credit Card (CC)'},{id:'AQUA',name:'Aqua Financing (AQUA)'},{id:'PO',name:'Purchase Order (PO)'}];
