  <details className="op-disclosure"><summary>Other · UTI, COLL, Service, ACCRF</summary>{data.canEdit&&<RequestForm team={team} save={save}/>}<div className="op-request-list">{(o.requests||[]).map((r:any)=><article key={r.id}><strong>{r.type} · {r.status}</strong><p>{r.details}</p>{r.type==='ACCRF'&&<p>Revised contract price: {currency(r.amount)}</p>}{me.role==='admin'&&r.status==='Pending'&&<><button disabled={saving} onClick={()=>act('reviewRequest',{id:r.id,approve:true})}>Approve and move to {r.type==='Service'?'SVC':r.type}</button><button disabled={saving} onClick={()=>act('reviewRequest',{id:r.id,approve:false})}>Decline</button></>}</article>)}</div>{me.role==='admin'&&<div className="live-danger-zone"><h3>Delete account</h3><p>Permanently remove this customer job and its Production Desk records.</p><button disabled={saving} onClick={()=>{if(window.confirm('Are you sure you want to delete this account?'))act('delete')}}>Delete account</button></div>}</details>
  {me.role==='admin'&&<details className="op-disclosure"><summary>Payments</summary><PaymentForm j={j} save={save}/></details>}
