function ScheduleForm({j,team,today,save}:any){const [day,setDay]=useState(j.install||today),[multi,setMulti]=useState(!!j.installEnd&&j.installEnd!==j.install),[end,setEnd]=useState(j.installEnd||j.install||today),[files,setFiles]=useState<File[]>([]);const late=(dayDifference(j.received,day)||0)>30;return <Form onSave={async f=>{const salesPhotos=[];for(const file of files)salesPhotos.push(await uploadAttachment(j.id,'photos',file));await save('schedule',{salesPhotos,date:day,endDate:multi?end:day,period:field(f,'time')?(Number(field(f,'time').slice(0,2))<12?'AM':'PM'):field(f,'period'),time:field(f,'time'),installerId:field(f,'installerId'),stop:Number(field(f,'stop')),paymentReference:field(f,'paymentReference'),additionalInstructions:field(f,'additionalInstructions')})}}><label className="op-check"><input type="checkbox" checked={multi} onChange={e=>setMulti(e.target.checked)}/>Multi-day</label>{multi&&<p className="op-muted">Scheduled Monday–Friday only. Weekends are skipped.</p>}<label>{multi?'Start date':'Install date'}<input type="date" required min={today} value={day} onChange={e=>{setDay(e.target.value);if(end<e.target.value)setEnd(e.target.value)}}/></label>{multi&&<label>End date<input type="date" min={day} value={end} required onChange={e=>setEnd(e.target.value)}/></label>}<Select label="AM / PM" name="period" value={j.installPeriod||'AM'} items={['AM','PM']}/><Select required={false} label="Start time (optional)" name="time" value={j.installTime||''} items={[{id:'',name:'Use AM / PM window'},...Array.from({length:24},(_,hour)=>{const id=String(hour).padStart(2,'0')+':00';return {id,name:hourLabel(id)}})]}/><Select label="Installer" name="installerId" value={j.installerId} items={team.filter((m:any)=>m.role==='installer'&&m.active!==0)}/><Input label="Stop number" name="stop" type="number" min="1" max="99" value={j.stopNumber||1} required/><label>Additional sales photos<input type="file" multiple accept="image/*" onChange={e=>setFiles(Array.from(e.target.files||[]))}/></label><Text name="additionalInstructions" label="Additional scheduling instructions" value={j.scheduleInstructions}/>{!j.permitReceived&&<p className="op-red">Permit Received and a permit number are required before scheduling.</p>}{late&&<><p className="op-callout">This appointment is beyond 30 days received and will age. Record payment in full first. Saving sends an approval request to the Field Supervisor; a supervisor may approve their own request.</p><Input label="Full-payment reference" name="paymentReference" required/></>}</Form>}
function StatusForm({j,save,admin}:any){if(j.operations?.report?.pending)return <Form onSave={async()=>save('reviewReport',{approve:true})}><Select name="result" label="Approve installer result" value={j.operations.report.status} items={[{id:j.operations.report.status,name:j.operations.report.status==='Complete'?'COMP — Approve Complete report':'INC — Approve Incomplete report'}]}/><p>✓ Installer result received. Saving approves the submitted result and updates the job status.</p></Form>;const canProd=j.stage==='Received'&&!!j.install,canProgress=['Production','InProgress'].includes(j.stage);if(!canProd&&!canProgress)return <p className="op-muted">Schedule an RCVD job before moving it to PROD.</p>;return <Form onSave={async f=>save('status',{target:field(f,'target')})}><Select name="target" label="New status" value={canProd?'Production':'InProgress'} items={[...(canProd?[{id:'Production',name:'PROD — Start production timer'}]:[]),...(canProgress?[{id:'InProgress',name:'IN PROGRESS — Multi-day installation'}]:[]),...(admin&&j.stage==='Production'?[{id:'Received',name:'RCVD — Return to received'}]:[])]}/></Form>}
function ReceiveForm({j,save}:any){const [rows,setRows]=useState<any[]>(j.materials?.length?j.materials:[{materialType:j.materialType||allowedMaterials(j.product)[0],brand:j.brand||'',bay:j.bay||''}]);return <Form onSave={async f=>save('receive',{received:field(f,'received'),materials:rows})}><Input name="received" label="Materials Received date" type="date" max={localDay()} value={j.received||localDay()} readOnly={!!j.received} required/>{rows.map((row,i)=><div key={i} className="live-receipt-row"><label>Product type<select value={row.materialType} onChange={e=>setRows(rows.map((r,n)=>n===i?{...r,materialType:e.target.value}:r))}>{allowedMaterials(j.product).map(v=><option key={v}>{v}</option>)}</select></label><label>Brand<select required value={row.brand} onChange={e=>setRows(rows.map((r,n)=>n===i?{...r,brand:e.target.value}:r))}><option value="">Select…</option>{brands.map(v=><option key={v}>{v}</option>)}</select></label><label>Bay location<input required value={row.bay} onChange={e=>setRows(rows.map((r,n)=>n===i?{...r,bay:e.target.value}:r))}/></label>{rows.length>1&&<button type="button" onClick={()=>setRows(rows.filter((_,n)=>n!==i))}>Remove product</button>}</div>)}<button type="button" onClick={()=>setRows([...rows,{materialType:allowedMaterials(j.product)[0],brand:'',bay:''}])}>Add product / bay</button></Form>}
function PermitDetails({j}:any){return <dl className="live-record">{[['Permit number',j.permitNumber],['Building Department',j.buildingDepartment],['Expiration date',j.permitExpiration],['Building Department phone',formatPhone(j.buildingDepartmentPhone||'')],['Private Provider',j.privateProvider?'Yes — virtual inspections':'No']].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value||'Not recorded'}</dd></div>)}</dl>}
function PermitForm({j,save}:any){const [received,setReceived]=useState(!!j.permitReceived);return <details><summary>Update permit</summary><Form onSave={async f=>save('permit',{received,number:field(f,'permitNumber'),buildingDepartment:field(f,'buildingDepartment'),expiration:field(f,'permitExpiration'),buildingDepartmentPhone:formatPhone(field(f,'buildingDepartmentPhone')),privateProvider:f.has('privateProvider')})}><Input name="permitNumber" label="Permit number" value={j.permitNumber} required={received}/><Input name="buildingDepartment" label="Building Department" value={j.buildingDepartment}/><Input name="permitExpiration" label="Expiration date" type="date" value={j.permitExpiration}/><Input name="buildingDepartmentPhone" label="Building Department phone number" type="tel" value={formatPhone(j.buildingDepartmentPhone||'')} onInput={(e:any)=>e.currentTarget.value=formatPhone(e.currentTarget.value)}/><label className="op-check"><input name="privateProvider" type="checkbox" defaultChecked={!!j.privateProvider}/>Private Provider — virtual inspections</label><label className="op-check"><input type="checkbox" checked={received} onChange={e=>setReceived(e.target.checked)}/>Permit Received</label></Form></details>}
function RequestForm({team,save}:any){const [type,setType]=useState('UTI');return <Form onSave={async f=>save('request',{type,details:field(f,'details'),paymentReference:field(f,'paymentReference'),refused:f.has('refused'),serviceDate:field(f,'serviceDate'),period:field(f,'period')||'AM',installerId:field(f,'installerId'),...(type==='ACCRF'?{amount:Number(field(f,'amount'))}:{})})}><label>Request type<select value={type} onChange={e=>setType(e.target.value)}>{['UTI','COLL','Service','ACCRF'].map(v=><option key={v}>{v}</option>)}</select></label><Text label="Details / work instructions" name="details"/>{type==='UTI'&&<Input name="paymentReference" label="Payment-in-full reference" required/>}{type==='COLL'&&<label className="op-check"><input name="refused" type="checkbox" required/>Customer refused payment</label>}{type==='Service'&&<><Input label="Service date" name="serviceDate" type="date" min={localDay()} required/><Select label="Period" name="period" value="AM" items={['AM','PM']}/><Select label="Assigned installer" name="installerId" items={team.filter((m:any)=>m.role==='installer'&&m.active!==0)}/></>}{type==='ACCRF'&&<Input label="Revised total contract price" name="amount" type="number" min="0" step=".01" required/>}<small>Administrator approval is required before this changes the job{type==='Service'?' to SVC and adds the service appointment.':'.'}</small></Form>}
function Gallery({attachments}:any){return attachments.length?<div className="op-gallery">{attachments.map((a:any)=><a key={a.key} href={'/api/attachments?key='+encodeURIComponent(a.key)} target="_blank" rel="noreferrer">{a.name}<small>{a.kind}</small></a>)}</div>:<p className="op-muted">No files yet.</p>}
function InstallerReport({j,save}:any){const [status,setStatus]=useState('Complete'),[attachments,setAttachments]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');const requirements=requiredReportKinds(status);const upload=async(kind:string,files:File[])=>{if(!files.length)return;setBusy(true);setError('');try{const uploaded:any[]=[];for(const file of files)uploaded.push(await uploadAttachment(j.id,kind,file));setAttachments(old=>['issue','photos'].includes(kind)?[...old,...uploaded]:[...old.filter(v=>v.kind!==kind),uploaded[0]])}catch(e){setError((e as Error).message)}finally{setBusy(false)}};return <><div className="live-requirements"><strong>{status} requires:</strong><span>Front photo</span><span>Back photo</span><span>Left-side photo</span><span>Right-side photo</span><span>{status==='Complete'?'Completion certificate':'Incomplete certificate'}</span>{status==='Incomplete'&&<span>One or more issue photos</span>}</div><Form onSave={async f=>{if(busy)throw Error('Wait for the upload to finish.');const missing=requirements.find(kind=>!attachments.some(a=>a.kind===kind));if(missing)throw Error(`Add ${reportLabels[missing].toLowerCase()} before submitting.`);await save('report',{id:crypto.randomUUID(),status,reason:field(f,'reason'),notes:field(f,'notes'),installed:field(f,'installed'),attachments})}}><label>Job result<select value={status} onChange={e=>{setStatus(e.target.value);setAttachments(old=>old.filter(a=>!['completion','incomplete','issue'].includes(a.kind)))}}><option>Complete</option><option>Incomplete</option></select></label><Input name="installed" label="Installation date" type="date" value={localDay()} max={localDay()} required/>{status==='Incomplete'&&<><Text label="Reason incomplete" name="reason"/>{!j.reorder&&<p className="op-callout">Reorder information must be entered by the office before the Field Supervisor can approve this INC result.</p>}</>}<Text label="Installer notes" name="notes"/>{requirements.map(kind=><label key={kind}>{reportLabels[kind]}<input type="file" multiple={kind==='issue'} accept="image/*,.pdf" disabled={busy} onChange={e=>upload(kind,Array.from(e.target.files||[]))}/><small>{attachments.filter(a=>a.kind===kind).map(a=>a.name).join(', ')||'Required'}</small></label>)}<label>Additional Photos (optional)<input type="file" multiple accept="image/*" disabled={busy} onChange={e=>upload('photos',Array.from(e.target.files||[]))}/><small>{attachments.filter(a=>a.kind==='photos').map(a=>a.name).join(', ')||'Optional'}</small></label>{busy&&<p>Uploading…</p>}{error&&<p className="op-red">{error}</p>}</Form></>}
function Quality({data,change,reload,onOpenJob}:any){const [selectedInstaller,setSelectedInstaller]=useState<any>(null);const {team,surveys,metrics,canReview,me,config}=data;return <><section className="op-panel"><h2>Guild Quality Scores</h2>{me.role==='admin'&&<ReportImport kind="guild" onImported={reload}/>}<p>{metrics.period.start} – {metrics.period.end}</p><div className="op-quality">{['Installation Crew','Quality of Workmanship','Clean & Safe','Installation Done Right'].map((c,i)=><div key={c}><span>{c}</span><strong>{metrics.categories[i]?.toFixed(2)??'—'}</strong></div>)}</div>{team.filter((m:any)=>m.role==='installer').map((m:any)=>{const rows=surveys.filter((s:any)=>s.installer_id===m.id&&s.completed_on>=metrics.period.start&&s.completed_on<=metrics.period.end);const avg=[0,1,2,3].map(i=>{const r=rows.map((s:any)=>s.ratings[i]).filter((v:any)=>v!=null);return r.length?r.reduce((sum:number,v:number)=>sum+v-1,0)/r.length:null});const q=avg.every(v=>v!==null)?avg.reduce((s:number,v:any)=>s+v,0)/4:null;return <div className="op-crew-surveys" key={m.id}><button className="op-appointment" onClick={()=>setSelectedInstaller(selectedInstaller?.id===m.id?null:m)} aria-expanded={selectedInstaller?.id===m.id} aria-controls={'surveys-'+m.id} aria-label={'View surveys for '+m.name}><strong>{m.name}</strong><QualityValue score={q}/></button>{selectedInstaller?.id===m.id&&<div id={'surveys-'+m.id}><SurveyDetails installer={m} surveys={surveys} jobs={data.jobs} period={metrics.period} onOpenJob={onOpenJob} onClose={()=>setSelectedInstaller(null)}/></div>}</div>})}</section>{canReview&&<details className="op-disclosure"><summary>Record Guild Quality survey</summary><Form onSave={async f=>change('survey',{externalId:field(f,'externalId'),installerId:field(f,'installerId'),completedOn:field(f,'completedOn'),ratings:[0,1,2,3].map(i=>field(f,'rating'+i)===''?null:Number(field(f,'rating'+i)))})}><Input label="Unique Guild survey reference" name="externalId" required/><Select label="Installer" name="installerId" items={team.filter((m:any)=>m.role==='installer')}/><Input label="Survey completion date" name="completedOn" type="date" max={localDay()} required/>{['Installation Crew','Workmanship','Clean & Safe','Done Right'].map((v,i)=><label key={v}>{v}<select name={'rating'+i}><option value="">No response</option>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} stars</option>)}</select></label>)}<small>Original 1–5 stars. Each category is converted to 0–4 before averaging.</small></Form></details>}</>}
function Visits({onOpen}:any){const [rows,setRows]=useState<any[]>([]),[q,setQ]=useState(''),[error,setError]=useState('');useEffect(()=>{liveApi('/api/job-visits/recent').then(d=>setRows(d.visits)).catch(e=>setError(e.message))},[]);return <section className="op-panel"><h2>Recent job visits</h2><input aria-label="Search visits" placeholder="Search customer or job ID" value={q} onChange={e=>setQ(e.target.value)}/>{error&&<p className="op-red">{error}</p>}{rows.filter(r=>[r.job.customer,r.job.number].join(' ').toLowerCase().includes(q.toLowerCase())).map(r=><button className="op-appointment" key={r.visit.id} onClick={()=>onOpen(r.job.id)}><strong>{r.job.customer}</strong><span>{r.visit.visitedOn} · Open job visits</span></button>)}{!rows.length&&<p>No visits yet.</p>}</section>}
function Connections(){const [data,setData]=useState<any>(null),[error,setError]=useState('');const load=()=>liveApi('/api/operations/connections').then(setData).catch(e=>setError(e.message));useEffect(()=>{load()},[]);return <section className="op-panel"><h2>Connections</h2>{error&&<p role="alert" className="op-red">{error}</p>}{data&&<><p>Sales system: {data.salesIntegration}</p><p>Guild Quality: {data.guildQuality}</p><p>Email: {data.emailConfigured?'Configured':'Not configured'}</p><p>Phone push: {data.pushConfigured?'Configured':'Not configured'}</p><p>Open Settings → Photo storage to check Supabase uploads.</p><h3>Sales representative email queue</h3>{data.emails.map((e:any)=><div className="op-appointment" key={e.id}><strong>{e.recipient}<small>{e.subject}</small></strong><span>{e.status==='accepted'?'Accepted by email provider':e.status}</span>{e.status!=='accepted'&&<button onClick={async()=>{try{await liveApi('/api/operations',{action:'retryEmail',id:e.id});load()}catch(err){setError((err as Error).message)}}}>Retry</button>}</div>)}</>}</section>}
function ProjectRecord({j}:any){const [data,setData]=useState<any>(null),[editing,setEditing]=useState(false),[error,setError]=useState('');const load=()=>liveApi('/api/customer-records?jobId='+j.id).then(setData).catch(e=>setError(e.message));useEffect(()=>{load()},[j.id]);const fields=[...new Map([...recordFields,...profileFields,...historyDateFields].map(v=>[v[0],v])).values()].filter(([k])=>!k.startsWith('permit')&&k!=='inspectionDate');return <>{error&&<p className="op-red">{error}</p>}{data&&<><p className="op-muted">Imported customer record. Its historical balance fields do not replace the operational amount due.</p>{j.importSource&&<p className="op-callout">Imported from {j.importSource.file}, page {j.importSource.page}. Names and notes may be clipped in the source. Missing address, permit, product breakdown and assignments need review. {j.stage==='Incomplete'&&!j.incompleteSince?'INC entry date is unconfirmed; excluded from aged totals until verified.':''}</p>}{data.canEdit&&<button className="live-button" onClick={()=>setEditing(!editing)}>Update record</button>}{editing?<Form onSave={async f=>{const record={...data.record};fields.forEach(([k])=>record[k]=field(f,k));await liveApi('/api/customer-records',{jobId:j.id,version:data.version,record});await load();setEditing(false)}}>{fields.map(([k,label])=><Input key={k} name={k} label={label} value={data.record[k]}/>)}</Form>:<dl className="live-record">{fields.filter(([k])=>data.record[k]).map(([k,label])=><div key={k}><dt>{label}</dt><dd>{data.record[k]}</dd></div>)}</dl>}{data.canEdit&&<Form onSave={async f=>{await liveApi('/api/customer-records',{jobId:j.id,version:data.version,note:field(f,'note'),kind:'Contact'});await load()}}><Text name="note" label="Add contact note"/></Form>}{data.events.map((e:any)=><p className="op-history" key={e.id}>{e.note}<small>{e.actor_name} · {e.created}</small></p>)}</>}</>}

function PaymentForm({j,save}:any){const [mode,setMode]=useState('payment');return <Form onSave={async f=>save(mode,{...(mode==='payment'?{paymentAmount:Number(field(f,'amount'))}:{amount:Number(field(f,'amount'))}),reference:field(f,'reference'),paymentType:field(f,'paymentType')})}><p>Current balance due: {currency(j.amount)}</p><label>Action<select value={mode} onChange={e=>setMode(e.target.value)}><option value="payment">Record payment</option><option value="balance">Reconcile balance from main system</option></select></label><Input key={mode} name="amount" label={mode==='payment'?'Payment amount':'Correct balance due'} type="number" min={mode==='payment'?'.01':'0'} max={mode==='payment'&&j.amount!=null?j.amount:undefined} step=".01" required/>{mode==='payment'&&<Select name="paymentType" label="Payment type" value={j.paymentMethod} items={paymentMethods}/>}<Input name="reference" label="Payment or source reference" required/></Form>}
